SELECT * FROM ods.seo_dimension_main a where 1=1
AND a.id = #{params.id}
AND a.name like '%${params.name}%'
order by a.name ASC LIMIT ${params.rows} OFFSET ${params.page}

SELECT *
FROM
ods.seo_dimension_main a
where 1=1

    AND a.id != #{params.id}


    AND a.name = #{params.name}

SELECT count(*) FROM ods.seo_dimension_main a where 1=1
AND a.id = #{params.id}
AND a.name like '%${params.name}%'

